const FOLDER_PLACEHOLDER_NAMES = 'active-cards-folder|worktree-folder|repository-folder|project-folder|releases-folder'
const CARD_PLACEHOLDER_NAMES = 'card-file|card-title|card-prompt'
const CONFLICT_PLACEHOLDER_NAMES = 'conflict-file|conflict-files'
const PLACEHOLDER_PATTERN = new RegExp(`\\{\\{\\s*(${FOLDER_PLACEHOLDER_NAMES}|${CARD_PLACEHOLDER_NAMES}|${CONFLICT_PLACEHOLDER_NAMES})\\s*\\}\\}`, 'gu')
const CARD_PROMPT_PLACEHOLDER_PATTERN = /\{\{\s*card-prompt\s*\}\}/u

export interface ActionFolderPlaceholderValues {
    activeCardsFolder: string
    projectFolder: string
    repositoryFolder: string
    releasesFolder: string
    worktreeFolder: string
}

export function resolvePlaceholders(
    text: string,
    context: ActionContext,
    folders: ActionFolderPlaceholderValues,
    extraPrompt: string,
): string {
    return text.replace(PLACEHOLDER_PATTERN, (_match, name: string) => {
        if (name === 'active-cards-folder') {
            if (!folders.activeCardsFolder) throw new Error('Cannot resolve active-cards-folder without a configured working folder')

            return folders.activeCardsFolder
        }
        if (name === 'worktree-folder') {
            if (!folders.worktreeFolder) throw new Error('Cannot resolve worktree-folder without a run checkout path')

            return folders.worktreeFolder
        }
        if (name === 'repository-folder') {
            if (!folders.repositoryFolder) throw new Error('Cannot resolve repository-folder without an opened repository path')

            return folders.repositoryFolder
        }
        if (name === 'project-folder') {
            if (!folders.projectFolder) throw new Error('Cannot resolve project-folder without a configured project path')

            return folders.projectFolder
        }
        if (name === 'releases-folder') {
            if (!folders.releasesFolder) throw new Error('Cannot resolve releases-folder without a configured releases folder')

            return folders.releasesFolder
        }

        if (name === 'card-prompt') return extraPrompt
        if (name === 'conflict-file') {
            if (!context.conflictFile) throw new Error('Cannot resolve conflict-file placeholder without a selected conflict file')

            return context.conflictFile
        }
        if (name === 'conflict-files') {
            if (!context.conflictFiles) throw new Error('Cannot resolve conflict-files placeholder without conflict files')

            return context.conflictFiles
        }

        if (name === 'card-title') {
            if (!context.title) throw new Error('Cannot resolve card-title placeholder without a card title')

            return context.title
        }

        if (!context.file) throw new Error('Cannot resolve card-file placeholder without a file context')

        return context.file
    })
}

export function resolveAgentPrompt(
    action: ActionDefinition,
    context: ActionContext,
    folders: ActionFolderPlaceholderValues,
    extraPrompt: string,
): string {
    if (!action.prompt) throw new Error(`Missing prompt for agent action "${action.label}"`)
    const resolvedText = resolvePlaceholders(action.prompt, context, folders, extraPrompt)
    if (CARD_PROMPT_PLACEHOLDER_PATTERN.test(action.prompt)) return resolvedText
    if (extraPrompt.trim().length === 0) return resolvedText

    return `${resolvedText}\n\n${extraPrompt}`
}

const { spawn } = require('node:child_process');
const { assertGitRoot, requireRootPath } = require('../../git/git_commands');
const { ActionCancellationError } = require('./action_cancellation_error');
const { resolvePlaceholders } = require('./action_text');

async function runCommand(project, command, signal, onOutput, spawnCommand = spawn) {
    const rootPath = requireRootPath(project);
    await assertGitRoot(rootPath);
    if (signal.aborted) throw new ActionCancellationError('Action cancelled');

    return new Promise((resolve, reject) => {
        const child = spawnCommand(command, { cwd: rootPath, shell: true, signal });
        let stderr = '';
        let stdout = '';
        child.stdout.on('data', (chunk) => {
            const output = chunk.toString();
            stdout += output;
            onOutput({ stderr: '', stdout: output });
        });
        child.stderr.on('data', (chunk) => {
            const output = chunk.toString();
            stderr += output;
            onOutput({ stderr: output, stdout: '' });
        });
        child.on('error', (error) => {
            if (signal.aborted) reject(new ActionCancellationError('Action cancelled'));
            else reject(error);
        });
        child.on('close', (exitCode) => {
            if (signal.aborted) {
                reject(new ActionCancellationError('Action cancelled'));
                return;
            }

            resolve({ command, exitCode: exitCode ?? 1, stderr, stdout });
        });
    });
}

function executeCommandAction(input) {
    const command = resolvePlaceholders(
        input.action.command,
        input.context,
        input.project,
        input.primaryProject,
        input.projectFolder,
        input.releasesFolder,
        input.activeCardsFolder,
        input.extraPrompt,
    );
    const onOutput = ({ stderr, stdout }) => input.onOutput({ command, stderr, stdout });

    return input.commandRunner(input.project, command, input.signal, onOutput);
}

module.exports = { executeCommandAction, runCommand };

const path = require('node:path');
const { requireRootPath } = require('../../git/git_commands');

const FOLDER_PLACEHOLDER_NAMES = 'active-cards-folder|worktree-folder|repository-folder|project-folder|releases-folder';
const CARD_PLACEHOLDER_NAMES = 'card-file|this-card|card-title|card-prompt';
const CONFLICT_PLACEHOLDER_NAMES = 'conflict-file|conflict-files';
const PLACEHOLDER_PATTERN = new RegExp(`\\{\\{\\s*(${FOLDER_PLACEHOLDER_NAMES}|${CARD_PLACEHOLDER_NAMES}|${CONFLICT_PLACEHOLDER_NAMES})\\s*\\}\\}`, 'gu');
const CARD_PROMPT_PLACEHOLDER_PATTERN = /\{\{\s*card-prompt\s*\}\}/u;

function resolvePlaceholders(text, context, runProject, primaryProject, projectFolder, releasesFolder, activeCardsFolder, extraPrompt) {
    return text.replace(PLACEHOLDER_PATTERN, (_match, name) => {
        if (name === 'active-cards-folder') {
            if (typeof activeCardsFolder !== 'string' || activeCardsFolder.length === 0) {
                throw new Error('Cannot resolve active-cards-folder placeholder without a configured working folder');
            }

            return path.resolve(requireRootPath(primaryProject), activeCardsFolder);
        }
        if (name === 'worktree-folder') return requireRootPath(runProject);
        if (name === 'repository-folder') return requireRootPath(primaryProject);
        if (name === 'project-folder') {
            if (typeof projectFolder !== 'string') {
                throw new Error('Cannot resolve project-folder placeholder without a configured project folder');
            }

            const repositoryFolder = requireRootPath(primaryProject);

            return projectFolder.length === 0 ? repositoryFolder : path.resolve(repositoryFolder, projectFolder);
        }
        if (name === 'releases-folder') {
            if (typeof releasesFolder !== 'string' || releasesFolder.length === 0) {
                throw new Error('Cannot resolve releases-folder placeholder without a configured releases folder');
            }

            return path.resolve(requireRootPath(primaryProject), releasesFolder);
        }
        if (name === 'card-prompt') return extraPrompt;
        if (name === 'conflict-file') {
            if (!context.conflictFile) throw new Error('Cannot resolve conflict-file placeholder without a selected conflict file');

            return context.conflictFile;
        }
        if (name === 'conflict-files') {
            if (!context.conflictFiles) throw new Error('Cannot resolve conflict-files placeholder without conflict files');

            return context.conflictFiles;
        }
        if (name === 'card-title') {
            if (!context.title) throw new Error('Cannot resolve card-title placeholder without a card title');

            return context.title;
        }
        if (!context.file) throw new Error(`Cannot resolve ${name} placeholder without a file context`);

        return context.file;
    });
}

function resolveAgentPrompt(action, context, runProject, primaryProject, projectFolder, releasesFolder, activeCardsFolder, extraPrompt) {
    const prompt = resolvePlaceholders(
        action.prompt,
        context,
        runProject,
        primaryProject,
        projectFolder,
        releasesFolder,
        activeCardsFolder,
        extraPrompt,
    );
    if (CARD_PROMPT_PLACEHOLDER_PATTERN.test(action.prompt) || extraPrompt.trim().length === 0) return prompt;

    return `${prompt}\n\n${extraPrompt}`;
}

module.exports = { resolveAgentPrompt, resolvePlaceholders };

