import type { Card, CardHeader, CardTypeConfig } from './data_types'
import { getCardIdPrefix } from './card_identifiers'

/** The kind of item an action entry point is attached to. */
export type ActionContextKind = 'card' | 'file' | 'folder' | 'merge-conflict' | 'project'

export type ActionContextFilterValueSource =
    'kind' | 'type' | 'state' | 'file' | 'folder' | 'worktree' | 'text'

export interface ActionContextFilterDescriptor {
    key: ActionAppliesToField
    label: string
    supportedContextKinds: ActionContextKind[]
    valueSource: ActionContextFilterValueSource
    validate: (value: string) => string | null
}

/**
 * The selected item an action is evaluated against. `appliesTo` keys are matched
 * field-by-field against this object, so every matchable property is a string.
 */
export interface ActionContext {
    /** Stable card identity used for activity ownership. */
    cardInternalId?: string
    /** Title of the selected card, used for placeholder resolution. */
    title?: string
    /** Card/file type derived from the id prefix, e.g. `feature`. */
    type?: string
    /** Card state / status, e.g. `design`. */
    state?: string
    /** Path to the markdown file, used for placeholder resolution. */
    file?: string
    /** Folder name for folder contexts. */
    folder?: string
    /** Selected conflicted repository-relative path. */
    conflictFile?: string
    /** Newline-separated conflicted repository-relative paths. */
    conflictFiles?: string
    /** Active desktop conflict session binding. */
    conflictSessionId?: string
    kind: ActionContextKind
    worktree?: string
    worktreeError?: string
    [key: string]: string | undefined
}

/**
 * Stable identity of the item an action runs against, used to match a popup to its
 * execution and conversation history. Mutable header fields (title, state, worktree)
 * are excluded on purpose: a run that edits its own card must keep the same identity.
 */
export function actionContextIdentity(context: ActionContext): string {
    if (context.kind === 'project') return 'project'
    if (context.kind === 'folder') return `folder�${context.folder ?? ''}`
    if (context.kind === 'merge-conflict') {
        return `merge-conflict�${context.conflictSessionId ?? ''}�${context.conflictFile ?? ''}`
    }

    return `${context.kind}�${context.cardInternalId ?? context.file ?? ''}`
}

/** Required-value validation shared by every applicability filter descriptor. */
export function validateActionContextFilterValue(value: string): string | null {
    return value.length > 0 ? null : 'Required value'
}

const ACTION_CONTEXT_FILTER_METADATA: Record<ActionAppliesToField, Omit<ActionContextFilterDescriptor, 'key'>> = {
    file: { label: 'Repository file', supportedContextKinds: ['card', 'file'], valueSource: 'file', validate: validateActionContextFilterValue },
    folder: { label: 'Repository folder', supportedContextKinds: ['folder'], valueSource: 'folder', validate: validateActionContextFilterValue },
    kind: { label: 'Target kind', supportedContextKinds: ['card', 'file', 'folder', 'merge-conflict', 'project'], valueSource: 'kind', validate: validateActionContextFilterValue },
    state: { label: 'Card state', supportedContextKinds: ['card', 'file'], valueSource: 'state', validate: validateActionContextFilterValue },
    type: { label: 'Context type', supportedContextKinds: ['card', 'file', 'folder'], valueSource: 'type', validate: validateActionContextFilterValue },
    worktree: { label: 'Worktree', supportedContextKinds: ['card', 'file', 'project'], valueSource: 'worktree', validate: validateActionContextFilterValue },
    worktreeError: { label: 'Worktree error', supportedContextKinds: ['card', 'file'], valueSource: 'text', validate: validateActionContextFilterValue },
}

export const ACTION_CONTEXT_FILTER_DESCRIPTORS: ActionContextFilterDescriptor[] = ACTION_APPLIES_TO_FIELDS.map((key) => ({
    key,
    ...ACTION_CONTEXT_FILTER_METADATA[key],
}))

/** Resolve the configured card type for a card id via its prefix (e.g. `F-005` â†’ `feature`). */
export function getCardType(cardTypes: CardTypeConfig[], id: string): string | undefined {
    const prefix = getCardIdPrefix(id)

    return cardTypes.find((cardType) => cardType.idPrefix === prefix)?.type
}

type MarkdownContextCard = Pick<Card, 'path'> & {
    header: Pick<CardHeader, 'id' | 'internalId' | 'status' | 'title' | 'worktreeError' | 'worktreeValue'>
}

function markdownContext(card: MarkdownContextCard, cardTypes: CardTypeConfig[], kind: ActionContextKind): ActionContext {
    const context: ActionContext = { file: card.path, kind, title: card.header.title }
    const type = getCardType(cardTypes, card.header.id)
    if (card.header.internalId) context.cardInternalId = card.header.internalId
    if (type) context.type = type
    if (card.header.status) context.state = card.header.status
    if (card.header.worktreeValue) context.worktree = card.header.worktreeValue
    if (card.header.worktreeError) context.worktreeError = card.header.worktreeError

    return context
}

/** Build the action context for a card shown in card view. */
export function cardContext(card: MarkdownContextCard, cardTypes: CardTypeConfig[]): ActionContext {
    if (!card.header.internalId) throw new Error(`Cannot build action context without an internal ID: ${card.path}`)

    return markdownContext(card, cardTypes, 'card')
}

/**
 * Build the action context for a markdown file in the tree/text view. Regular markdown files
 * are not cards and carry no internal ID, so the context stays without card identity.
 */
export function fileContext(card: Card, cardTypes: CardTypeConfig[]): ActionContext {
    return markdownContext(card, cardTypes, 'file')
}

/** Build the action context for a folder node in the tree. */
export function folderContext(folder: string, isSpecial = false): ActionContext {
    const context: ActionContext = { folder, kind: 'folder' }
    if (isSpecial) context.type = folder

    return context
}

/** Build context for actions that run against the opened project rather than a card or file. */
export function projectContext(): ActionContext {
    return { kind: 'project' }
}

/** Add or remove the session assignment used by project-wide popup actions. */
export function projectContextWithWorktree(context: ActionContext, worktree: number | null): ActionContext {
    if (context.kind !== 'project') return context
    if (worktree === null) {
        const unassignedContext = { ...context }
        delete unassignedContext.worktree

        return unassignedContext
    }

    return { ...context, worktree: String(worktree) }
}

/**
 * True when the action is allowed in the given context. An action with no
 * `appliesTo` (like the built-in custom prompt) matches every context; otherwise
 * every `appliesTo` key must equal the same field on the context.
 */
export function actionMatchesContext(action: ActionDefinition, context: ActionContext): boolean {
    if (!action.appliesTo) return true

    return ACTION_APPLIES_TO_FIELDS.every((key) => action.appliesTo?.[key] === undefined || context[key] === action.appliesTo[key])
}

/** All actions that should be shown for a context, preserving load order. */
export function actionsForContext(actions: ActionDefinition[], context: ActionContext): ActionDefinition[] {
    return actions.filter((action) => (!action.builtin || action.id === CUSTOM_PROMPT_ACTION_ID) && actionMatchesContext(action, context))
}

/** Context actions in selector order, with the built-in custom prompt last. */
export function displayActionsForContext(actions: ActionDefinition[], context: ActionContext): ActionDefinition[] {
    const contextActions = actionsForContext(actions, context)
    const customPrompt = contextActions.find(({ id }) => id === CUSTOM_PROMPT_ACTION_ID)
    const configuredActions = contextActions.filter(({ id }) => id !== CUSTOM_PROMPT_ACTION_ID)

    return customPrompt ? [...configuredActions, customPrompt] : configuredActions
}

import { useCallback, useRef, useSyncExternalStore } from 'react'
import type { AgentConversation, AgentConversationError, Card, CardHeader } from '../../data/data_types'
import {
    CARD_ADDED_EVENT,
    CARD_REMOVED_EVENT,
    cardFieldChangedEvent,
    dataService,
    type CardAddedEventDetail,
    type CardField,
    type CardRemovedEventDetail,
    type DataService,
} from '../../services/data/data_service'

export interface CardWorktreeSnapshot {
    error: string | null | undefined
    value: string | null | undefined
    worktree: number | null | undefined
}

export interface CardConversationSnapshot {
    conversations: AgentConversation[]
    errors: AgentConversationError[]
}

export interface CardMetadataSnapshot {
    header: Omit<CardHeader, 'affects' | 'agentLogReferences'>
    isActive: boolean
    path: string
}

export interface CardAffectsSnapshot {
    affects: string[]
    id: string
    path: string
}

function findCard(path: string | null, service: DataService) {
    if (!path) return null

    return service.getState().snapshot?.activeCards.find((card) => card.path === path) ?? null
}

export function getProjectCard(path: string, service: DataService = dataService) {
    return findCard(path, service)
}

function eventMatchesPath(event: Event, path: string | null) {
    const { card } = (event as CustomEvent<CardAddedEventDetail | CardRemovedEventDetail>).detail

    return card.path === path
}

function useCardField<T>(path: string | null, field: CardField, select: (card: Card | null) => T, service: DataService) {
    const subscribe = useCallback((onStoreChange: () => void) => {
        const handleLifecycle = (event: Event) => {
            if (eventMatchesPath(event, path)) onStoreChange()
        }
        const fieldEvent = path ? cardFieldChangedEvent(path, field) : null
        if (fieldEvent) service.addEventListener(fieldEvent, onStoreChange)
        service.addEventListener(CARD_ADDED_EVENT, handleLifecycle)
        service.addEventListener(CARD_REMOVED_EVENT, handleLifecycle)

        return () => {
            if (fieldEvent) service.removeEventListener(fieldEvent, onStoreChange)
            service.removeEventListener(CARD_ADDED_EVENT, handleLifecycle)
            service.removeEventListener(CARD_REMOVED_EVENT, handleLifecycle)
        }
    }, [field, path, service])
    const getSnapshot = useCallback(() => select(findCard(path, service)), [path, select, service])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

const selectTitle = (card: Card | null) => card?.header.title ?? null
const selectBody = (card: Card | null) => card?.content ?? null
const selectPolicy = (card: Card | null) => card?.header.policy ?? null
const CARD_METADATA_FIELDS: CardField[] = ['identity', 'policy', 'status', 'title', 'worktree']

/** Reads only title primitive for one card. */
export function useCardTitle(path: string | null, service: DataService = dataService) {
    return useCardField(path, 'title', selectTitle, service)
}

/** Reads only body primitive for one card. */
export function useCardBody(path: string | null, service: DataService = dataService) {
    return useCardField(path, 'body', selectBody, service)
}

/** Reads only policy map reference for one card. */
export function useCardPolicy(path: string | null, service: DataService = dataService) {
    return useCardField(path, 'policy', selectPolicy, service)
}

/** Reads stable worktree projection for one card. */
export function useCardWorktree(path: string | null, service: DataService = dataService) {
    const snapshotRef = useRef<CardWorktreeSnapshot | null>(null)
    const select = useCallback((card: Card | null) => {
        if (!card) return null
        const next = { error: card.header.worktreeError, value: card.header.worktreeValue, worktree: card.header.worktree }
        const previous = snapshotRef.current
        const unchanged = previous
            && previous.error === next.error
            && previous.value === next.value
            && previous.worktree === next.worktree
        if (unchanged) return previous

        snapshotRef.current = next

        return next
    }, [])

    return useCardField(path, 'worktree', select, service)
}

/** Reads conversation state independently from persisted card fields. */
export function useCardConversations(path: string | null, service: DataService = dataService) {
    const snapshotRef = useRef<CardConversationSnapshot | null>(null)
    const select = useCallback((card: Card | null) => {
        if (!card) return null
        const previous = snapshotRef.current
        const unchanged = previous
            && previous.conversations === card.agentConversations
            && previous.errors === card.agentConversationErrors
        if (unchanged) return previous

        const next = { conversations: card.agentConversations, errors: card.agentConversationErrors }
        snapshotRef.current = next

        return next
    }, [])

    return useCardField(path, 'conversation', select, service)
}

function sameCardMetadata(previous: CardMetadataSnapshot, card: Card) {
    const header = previous.header
    return previous.path === card.path
        && previous.isActive === card.isActive
        && header.id === card.header.id
        && header.internalId === card.header.internalId
        && header.status === card.header.status
        && header.title === card.header.title
        && header.policy === card.header.policy
        && header.worktree === card.header.worktree
        && header.worktreeError === card.header.worktreeError
        && header.worktreeValue === card.header.worktreeValue
}

function cardMetadataSnapshot(card: Card): CardMetadataSnapshot {
    const { header: source } = card
    const header = {
        after: source.after,
        author: source.author,
        id: source.id,
        internalId: source.internalId,
        owner: source.owner,
        policy: source.policy,
        status: source.status,
        title: source.title,
        worktree: source.worktree,
        worktreeError: source.worktreeError,
        worktreeValue: source.worktreeValue,
    }

    return {
        header,
        isActive: card.isActive,
        path: card.path,
    }
}

/** Stable metadata-only projection. Body and activity changes cannot update it. */
export function useCardMetadata(path: string | null, service: DataService = dataService) {
    const cardRef = useRef<CardMetadataSnapshot | null>(null)
    const select = useCallback((card: Card | null) => {
        if (card && cardRef.current && sameCardMetadata(cardRef.current, card)) return cardRef.current
        cardRef.current = card ? cardMetadataSnapshot(card) : null

        return cardRef.current
    }, [])
    const subscribe = useCallback((onStoreChange: () => void) => {
        const handleLifecycle = (event: Event) => {
            if (eventMatchesPath(event, path)) onStoreChange()
        }
        const fieldEvents = path ? CARD_METADATA_FIELDS.map((field) => cardFieldChangedEvent(path, field)) : []
        fieldEvents.forEach((eventName) => service.addEventListener(eventName, onStoreChange))
        service.addEventListener(CARD_ADDED_EVENT, handleLifecycle)
        service.addEventListener(CARD_REMOVED_EVENT, handleLifecycle)

        return () => {
            fieldEvents.forEach((eventName) => service.removeEventListener(eventName, onStoreChange))
            service.removeEventListener(CARD_ADDED_EVENT, handleLifecycle)
            service.removeEventListener(CARD_REMOVED_EVENT, handleLifecycle)
        }
    }, [path, service])
    const getSnapshot = useCallback(() => select(findCard(path, service)), [path, select, service])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

/** Stable affects-only projection for affects editor. */
export function useCardAffects(path: string | null, service: DataService = dataService) {
    const snapshotRef = useRef<CardAffectsSnapshot | null>(null)
    const select = useCallback((card: Card | null) => {
        if (!card) return null
        const previous = snapshotRef.current
        const unchanged = previous
            && previous.affects === card.header.affects
            && previous.id === card.header.id
            && previous.path === card.path
        if (unchanged) return previous

        const next = { affects: card.header.affects, id: card.header.id, path: card.path }
        snapshotRef.current = next

        return next
    }, [])

    return useCardField(path, 'affects', select, service)
}

export const CARD_CHANGED_EVENT = 'cardChanged'

export const CARD_FIELDS = [
    'affects',
    'body',
    'conversation',
    'identity',
    'ordering',
    'policy',
    'status',
    'title',
    'worktree',
] as const

export type CardField = typeof CARD_FIELDS[number]

/** Event name scoped to one card and one stable view projection. */
export function cardFieldChangedEvent(path: string, field: CardField) {
    return `${CARD_CHANGED_EVENT}:${encodeURIComponent(path)}:${field}`
}

/** Event name for collection projections affected by one field across cards. */
export function cardCollectionFieldChangedEvent(field: CardField) {
    return `${CARD_CHANGED_EVENT}:all:${field}`
}

import type { Card, CardHeader, MarkdownFile } from '../../data/data_types'
import { generateUuid } from '../../data/uuid'

const HEADER_DELIMITER = '---'
const MARKDOWN_EXTENSION = '.md'
const DEFAULT_IMPORTED_STATUS = 'new'
const DEFAULT_IMPORTED_ID = 'F_0'
const TITLE_PREFIX = '# '
const LIST_ITEM_PREFIX = '  - '
const CHILD_INDENT = '  '

export type HeaderValue = string | string[] | Record<string, string>
export type MarkdownHeaderFields = Record<string, HeaderValue>

export interface ParsedMarkdown {
    body: string
    header: MarkdownHeaderFields
    rawHeader: string
}

export interface CardParseError {
    error: unknown
    path: string
}

export interface NewCardHeader {
    affects?: string[]
    /** Activity conversation references serialized through the existing `agents` frontmatter field. */
    agentLogReferences?: string[]
    author?: string | null
    id: string
    internalId: string
    owner?: string | null
    policy?: Record<string, boolean>
    sentryBaseUrl?: string
    sentryIssueId?: string
    sentryOrganization?: string
    status?: string | null
    title: string
}

interface HeaderSplit {
    body: string
    hasHeader: boolean
    rawHeader: string
}

interface CardSourceState {
    body: string
    content: string
    header: CardHeader
    headerFields: MarkdownHeaderFields
}

const sourceByCard = new WeakMap<Card, CardSourceState>()

function cloneCardHeader(header: CardHeader): CardHeader {
    return {
        ...header,
        affects: [...header.affects],
        agentLogReferences: [...header.agentLogReferences],
        policy: { ...header.policy },
    }
}

function requireCardSource(card: Card) {
    const source = sourceByCard.get(card)
    if (!source) throw new Error(`Cannot serialize card without parser source metadata: ${card.path}`)

    return source
}

function sameStringArray(left: string[], right: string[]) {
    return left.length === right.length && left.every((value, index) => value === right[index])
}

function sameBooleanMap(left: Record<string, boolean>, right: Record<string, boolean>) {
    const leftEntries = Object.entries(left)
    const rightEntries = Object.entries(right)

    return leftEntries.length === rightEntries.length && leftEntries.every(([key, value]) => right[key] === value)
}

function serializePolicy(policy: Record<string, boolean>) {
    return Object.fromEntries(Object.entries(policy).map(([key, enabled]) => [key, enabled ? 'true' : 'false']))
}

function setNullableHeaderField(fields: MarkdownHeaderFields, key: string, value: string | null) {
    if (value === null) delete fields[key]
    else fields[key] = value
}

function currentHeaderFields(card: Card, source: CardSourceState): MarkdownHeaderFields {
    const fields = cloneHeaderFields(source.headerFields)
    const { header } = card
    const sourceHeader = source.header

    if (!sameStringArray(header.affects, sourceHeader.affects)) fields.affects = [...header.affects]
    if (header.after !== sourceHeader.after) setNullableHeaderField(fields, 'after', header.after)
    if (!sameStringArray(header.agentLogReferences, sourceHeader.agentLogReferences)) fields.agents = [...header.agentLogReferences]
    if (header.author !== sourceHeader.author) setNullableHeaderField(fields, 'author', header.author)
    if (header.branch !== sourceHeader.branch) setNullableHeaderField(fields, 'branch', header.branch ?? null)
    if (header.id !== sourceHeader.id) fields.id = header.id
    if (header.internalId !== sourceHeader.internalId) setNullableHeaderField(fields, 'internalId', header.internalId)
    if (header.owner !== sourceHeader.owner) setNullableHeaderField(fields, 'owner', header.owner)
    if (!sameBooleanMap(header.policy, sourceHeader.policy)) fields.policy = serializePolicy(header.policy)
    if (header.sentryBaseUrl !== sourceHeader.sentryBaseUrl) {
        setNullableHeaderField(fields, 'sentryBaseUrl', header.sentryBaseUrl ?? null)
    }
    if (header.sentryIssueId !== sourceHeader.sentryIssueId) {
        setNullableHeaderField(fields, 'sentryIssueId', header.sentryIssueId ?? null)
    }
    if (header.sentryOrganization !== sourceHeader.sentryOrganization) {
        setNullableHeaderField(fields, 'sentryOrganization', header.sentryOrganization ?? null)
    }
    if (header.status !== sourceHeader.status) setNullableHeaderField(fields, 'status', header.status)
    if (header.title !== sourceHeader.title) fields.title = header.title
    if (header.worktree !== sourceHeader.worktree || header.worktreeError !== sourceHeader.worktreeError) {
        if (header.worktree === null || header.worktree === undefined) delete fields.worktree
        else fields.worktree = String(header.worktree)
    }

    return fields
}

function detectLineEnding(content: string) {
    return content.includes('\r\n') ? '\r\n' : '\n'
}

function splitHeader(content: string): HeaderSplit {

function frameDocument(headerLines: string[], body: string, lineEnding: string) {
    return `${HEADER_DELIMITER}${lineEnding}${headerLines.join(lineEnding)}${lineEnding}${HEADER_DELIMITER}${lineEnding}${body}`
}

function replaceCardBodyTitle(body: string, title: string) {
    return body.replace(/^# .*$/m, `${TITLE_PREFIX}${title}`)
}

function serializeNewHeader(header: NewCardHeader) {
    if (!header.id) throw new Error('Cannot generate a card without an id')
    if (!header.internalId) throw new Error('Cannot generate a card without an internalId')
    if (!header.title) throw new Error('Cannot generate a card without a title')

    const affects = header.affects ?? []
    const agentLogReferences = header.agentLogReferences ?? []
    const policy = header.policy ?? {}

    const lines: string[] = []
    lines.push(`author: ${header.author ?? ''}`)
    lines.push(`id: ${header.id}`)
    lines.push(`internalId: ${header.internalId}`)
    lines.push(`title: ${header.title}`)
    lines.push(`status: ${header.status ?? DEFAULT_IMPORTED_STATUS}`)
    lines.push(`owner: ${header.owner ?? ''}`)
    lines.push('affects:', ...affects.map((entry) => `${LIST_ITEM_PREFIX}${entry}`))
    lines.push('agents:', ...agentLogReferences.map((entry) => `${LIST_ITEM_PREFIX}${entry}`))
    lines.push('policy:', ...Object.entries(policy).map(([key, value]) => `${CHILD_INDENT}${key}: ${value ? 'true' : 'false'}`))
    if (header.sentryIssueId) lines.push(`sentryIssueId: ${header.sentryIssueId}`)
    if (header.sentryOrganization) lines.push(`sentryOrganization: ${header.sentryOrganization}`)
    if (header.sentryBaseUrl) lines.push(`sentryBaseUrl: ${header.sentryBaseUrl}`)

    return lines.join('\n')
}

export const markdownParsingService = {
    followsCardNamingConvention,

    isMarkdownFile,

    isRootWorkingFolderFile,

    parse(content: string): ParsedMarkdown {
        const { body, rawHeader } = splitHeader(content)

        return { body, header: parseHeaderFields(rawHeader), rawHeader }
    },

    /**
     * Parses a markdown file into a card. `isActive` marks the working folder root files,
     * which are the only ones that are always cards and always get an `internalId`.
     * Archived and released files are cards when they already carry an `internalId`;
     * all other markdown is a regular document that never receives one.
     * See the card classification rule in design/architecture/current_data_model.md.
     */
    parseCard(file: MarkdownFile, workingFolder: string): Card {
        const { body, hasHeader, rawHeader } = splitHeader(file.content)
        const fields = parseHeaderFields(rawHeader)
        const header = parseCardHeader(fields, file, body)
        const card: Card = {
            agentConversationErrors: [],
            agentConversations: [],
            content: body,
            hasFrontmatter: hasHeader,
            header,
            isActive: isRootWorkingFolderFile(file.path, workingFolder),
            path: file.path,
            sha: file.sha,
        }
        sourceByCard.set(card, { body, content: file.content, header: cloneCardHeader(header), headerFields: cloneHeaderFields(fields) })

        return card
    },

    serializeCard(card: Card): MarkdownFile {
        const source = requireCardSource(card)
        const headerFields = currentHeaderFields(card, source)
        const keys = [...new Set([...Object.keys(source.headerFields), ...Object.keys(headerFields)])]
        let content = source.content

        for (const key of keys) {
            const sourceValue = source.headerFields[key]
            const currentValue = headerFields[key]
            if (sameHeaderValue(sourceValue, currentValue)) continue

            content = rewriteHeaderValue(content, key, currentValue)
        }
        if (card.content !== source.body) content = this.replaceBody(content, card.content)

        return { content, path: card.path, ...(card.sha ? { sha: card.sha } : {}) }
    },

    acknowledgeSerializedCard(card: Card, file: MarkdownFile) {
        const { body, rawHeader } = splitHeader(file.content)
        const headerFields = parseHeaderFields(rawHeader)
        sourceByCard.set(card, {
            body,
            content: file.content,
            header: parseCardHeader(headerFields, file, body),
            headerFields: cloneHeaderFields(headerFields),
        })
    },

    hasSourceContent(card: Card, content: string) {
        return sourceByCard.get(card)?.content === content
    },

    splitCards(files: MarkdownFile[], workingFolder: string) {
        const markdownFiles = files.filter((file) => isMarkdownFile(file.path))
        const activeCards: Card[] = []

    return path.split('/').at(-1) ?? path
}

function isMarkdownFile(path: string) {
    return path.toLowerCase().endsWith(MARKDOWN_EXTENSION)
}

function isRootWorkingFolderFile(path: string, workingFolder: string) {
    const normalizedPath = path.replace(/\\/g, '/')
    const prefix = `${workingFolder}/`
    const remainingPath = normalizedPath.startsWith(prefix) ? normalizedPath.slice(prefix.length) : normalizedPath

    return !remainingPath.includes('/') && isMarkdownFile(remainingPath)
}

function followsCardNamingConvention(path: string) {
    return /^[A-Z]+([_-])\d+\1.+\.md$/u.test(getFileName(path))
}

function parseCardHeader(fields: MarkdownHeaderFields, file: MarkdownFile, body: string): CardHeader {
    const fileName = getFileName(file.path)
