    'updateActionConversationViewed',
    'updateCardActionSettings',
];
const EVENT_METHODS = new Set(['runSearchRegexpAgent']);
const CODEX_RUNTIME_METHODS = ['getCodexRateLimits'];

let nextEventId = 1;
let desktopConfig = readArgumentJson('md2-desktop-config', {});

function readArgumentValue(name) {
    const prefix = `--${name}=`;
    const argument = process.argv.find((candidate) => candidate.startsWith(prefix));

    return argument ? argument.slice(prefix.length) : null;
}

function readArgumentJson(name, fallback) {
    const value = readArgumentValue(name);
    if (!value) return fallback;

    return JSON.parse(decodeURIComponent(value));
}

function createEventId(method) {
    const eventId = `${method}-${nextEventId}`;
    nextEventId += 1;

    return eventId;
}

function invokeBridge(method, params, callback) {
    const eventId = EVENT_METHODS.has(method) && callback ? createEventId(method) : null;
    let listener = null;

    if (eventId) {
        listener = (_event, message) => {
            if (message.eventId === eventId) callback(message.payload);
        };
        ipcRenderer.on(LOCAL_BRIDGE_EVENT_CHANNEL, listener);
    }

    return ipcRenderer.invoke(LOCAL_BRIDGE_INVOKE_CHANNEL, { eventId, method, params }).finally(() => {
        if (listener) ipcRenderer.removeListener(LOCAL_BRIDGE_EVENT_CHANNEL, listener);
    });
}

function subscribeBridge(method, params, callback) {
    const subscriptionId = createEventId(method);
    const listener = (_event, message) => {
        if (message.eventId === subscriptionId) callback(message.payload);
    };

    ipcRenderer.on(LOCAL_BRIDGE_EVENT_CHANNEL, listener);
    ipcRenderer.send(LOCAL_BRIDGE_SUBSCRIBE_CHANNEL, { method, params, subscriptionId });

    return () => {
        ipcRenderer.removeListener(LOCAL_BRIDGE_EVENT_CHANNEL, listener);
        ipcRenderer.send(LOCAL_BRIDGE_UNSUBSCRIBE_CHANNEL, subscriptionId);
    };
}

function createBridge(methods) {
    return Object.fromEntries(methods.map((method) => [
        method,
        (...params) => {
            const callback = EVENT_METHODS.has(method) && typeof params[params.length - 1] === 'function'
                ? params.pop()
                : null;

            return invokeBridge(method, params, callback);
        },
    ]));
}

function exposeWarning(message) {
    const render = () => {
        document.body.innerHTML = '';
        const warning = document.createElement('main');
        warning.setAttribute('role', 'alert');
        warning.style.cssText = 'font-family: system-ui, sans-serif; padding: 24px; color: #7f1d1d;';
        warning.textContent = message;
        document.body.appendChild(warning);
    };

    if (document.body) {
        render();
        return;
    }

    window.addEventListener('DOMContentLoaded', render);
}

function isAllowedOrigin() {
    const trustedLocation = readArgumentValue('md2-bridge-trusted-location');
    if (trustedLocation) {
        const currentUrl = new URL(window.location.href);
        const trustedUrl = new URL(decodeURIComponent(trustedLocation));
        currentUrl.hash = '';
        trustedUrl.hash = '';
        if (currentUrl.href === trustedUrl.href) return true;
    }

    const allowedOrigins = readArgumentJson('md2-bridge-allowed-origins', []);

    return allowedOrigins.includes(window.location.origin);
}

if (!isAllowedOrigin()) {
    exposeWarning(`MDÂ² desktop bridges blocked for origin: ${window.location.origin}`);
} else {
    const themeBridge = { setThemeMode: (mode) => ipcRenderer.send(THEME_SET_MODE_CHANNEL, mode) };
    const lifecycleBridge = {
        reportFlushResult: (result) => ipcRenderer.send(LIFECYCLE_FLUSH_RESULT_CHANNEL, result),
        onFlushRequested: (callback) => {
            const listener = (_event, request) => callback(request);
            ipcRenderer.on(LIFECYCLE_FLUSH_REQUEST_CHANNEL, listener);

            return () => ipcRenderer.removeListener(LIFECYCLE_FLUSH_REQUEST_CHANNEL, listener);
        },
    };
    const configBridge = {
        getDesktopConfig: () => desktopConfig,
        setDesktopConfig: async (values) => {
            desktopConfig = await ipcRenderer.invoke(CONFIG_SET_DESKTOP_CHANNEL, values);

            return desktopConfig;
        },
    };
    const remoteControlBridge = {
        getStatus: () => ipcRenderer.invoke(REMOTE_CONTROL_GET_STATUS_CHANNEL),
        onStatusChange: (callback) => {
            const listener = (_event, status) => callback(status);
            ipcRenderer.on(REMOTE_CONTROL_STATUS_CHANNEL, listener);

            return () => ipcRenderer.removeListener(REMOTE_CONTROL_STATUS_CHANNEL, listener);
        },
        start: () => ipcRenderer.invoke(REMOTE_CONTROL_START_CHANNEL),
        stop: () => ipcRenderer.invoke(REMOTE_CONTROL_STOP_CHANNEL),
    };
    const remarkableBridge = {
        importFiles: (request) => ipcRenderer.invoke(REMARKABLE_IMPORT_FILES_CHANNEL, request),
        listImageFiles: (settings) => ipcRenderer.invoke(REMARKABLE_LIST_IMAGE_FILES_CHANNEL, settings),
        testConnection: (settings) => ipcRenderer.invoke(REMARKABLE_TEST_CONNECTION_CHANNEL, settings),
    };
    const dataBridge = {
        ...createBridge(DATA_METHODS),
        onMergeConflictSessionChanged: (callback) => subscribeBridge('onMergeConflictSessionChanged', [], callback),
        onWorktreesChanged: (callback) => subscribeBridge('onWorktreesChanged', [], callback),
        watchProject: (project, callback) => subscribeBridge('watchProject', [project], callback),
    };
    const actionBridge = {
        ...createBridge(ACTION_METHODS),
        onActionRun: (callback) => subscribeBridge('onActionRun', [], callback),
    };
    const codexRuntimeBridge = {
        ...createBridge(CODEX_RUNTIME_METHODS),
        onCodexRateLimits: (callback) => subscribeBridge('onCodexRateLimits', [], callback),
        onCodexUpdateRequired: (callback) => subscribeBridge('onCodexUpdateRequired', [], callback),
        updateCodexCli: () => invokeBridge('updateCodexCli', [], null),
    };
    const updatesBridge = {
        downloadUpdate: (downloadUrl) => ipcRenderer.invoke(UPDATE_DOWNLOAD_CHANNEL, { downloadUrl }),
        onDownloadProgress: (callback) => {
            const listener = (_event, progress) => callback(progress);
            ipcRenderer.on(UPDATE_PROGRESS_CHANNEL, listener);

            return () => ipcRenderer.removeListener(UPDATE_PROGRESS_CHANNEL, listener);
        },
        onUpdateAvailable: (callback) => {
            const listener = (_event, info) => callback(info);
            ipcRenderer.on(UPDATE_AVAILABLE_CHANNEL, listener);

            return () => ipcRenderer.removeListener(UPDATE_AVAILABLE_CHANNEL, listener);
        },
    };

    contextBridge.exposeInMainWorld('md2Theme', themeBridge);
    contextBridge.exposeInMainWorld('md2Lifecycle', lifecycleBridge);
    contextBridge.exposeInMainWorld('md2Config', configBridge);
    contextBridge.exposeInMainWorld('md2RemoteControl', remoteControlBridge);
    contextBridge.exposeInMainWorld('md2Remarkable', remarkableBridge);
    contextBridge.exposeInMainWorld('md2Data', dataBridge);
    contextBridge.exposeInMainWorld('md2Actions', actionBridge);
    contextBridge.exposeInMainWorld('md2CodexRuntime', codexRuntimeBridge);
    contextBridge.exposeInMainWorld('md2Updates', updatesBridge);
}

import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext'
import { useCellValue } from '@mdxeditor/editor'
import {
    $getSelection,
    $isRangeSelection,
    COMMAND_PRIORITY_HIGH,
    COPY_COMMAND,
    KEY_DOWN_COMMAND,
    PASTE_COMMAND,
    type PasteCommandType,
} from 'lexical'
import { useCallback, useEffect, useRef } from 'react'
import { dialogService } from '../../services/dialog_service'
import { useDialogError } from '../hooks/use_dialog_error'
import { markdownPasteConfig$ } from './markdown_paste_cell'

const MARKDOWN_MIME_TYPE = 'text/markdown'
const PLAIN_TEXT_MIME_TYPE = 'text/plain'

interface ShortcutIntent {
    generation: number
    shifted: boolean
}

function trackShortcutIntent(intent: ShortcutIntent, shifted: boolean) {
    intent.generation += 1
    intent.shifted = shifted
    const generation = intent.generation
    setTimeout(() => {
        if (intent.generation === generation) intent.shifted = false
    }, 0)
}

function consumeShiftedIntent(intent: ShortcutIntent) {
    const shifted = intent.shifted
    intent.shifted = false
    return shifted
}

function isControlShortcut(event: KeyboardEvent, key: string) {
    return event.ctrlKey && !event.altKey && !event.metaKey && event.key.toLowerCase() === key
}

function clipboardImageFile(clipboardData: DataTransfer) {
    if (!clipboardData.items) return null
    const imageItem = [...clipboardData.items].find(({ kind, type }) => kind === 'file' && type.startsWith('image/'))

    return imageItem?.getAsFile() ?? null
}

/** Handles Markdown-aware and literal-text clipboard operations for MDXEditor. */
export function MarkdownPastePlugin() {
    const config = useCellValue(markdownPasteConfig$)
    const [editor] = useLexicalComposerContext()
    const copyIntentRef = useRef<ShortcutIntent>({ generation: 0, shifted: false })
    const pasteIntentRef = useRef<ShortcutIntent>({ generation: 0, shifted: false })
    const configError = config ? null : new Error('Cannot register Markdown paste without configuration')
    useDialogError(configError, 'Markdown paste is unavailable')

    const handleKeyDown = useCallback((event: KeyboardEvent) => {
        if (isControlShortcut(event, 'c')) trackShortcutIntent(copyIntentRef.current, event.shiftKey)
        if (isControlShortcut(event, 'v')) trackShortcutIntent(pasteIntentRef.current, event.shiftKey)
        return false
    }, [])

    const handleCopy = useCallback((event: ClipboardEvent | KeyboardEvent | null) => {
        const shifted = consumeShiftedIntent(copyIntentRef.current)
        if (!config || !event || !('clipboardData' in event) || !event.clipboardData) return false

        const selection = $getSelection()
        if (!$isRangeSelection(selection) || selection.isCollapsed()) return false

        try {
            const plainText = selection.getTextContent()
            if (shifted) {
                event.clipboardData.setData(PLAIN_TEXT_MIME_TYPE, plainText)
            } else {
                const markdown = config.getSelectionMarkdown()
                if (!markdown) throw new Error('Selected content could not be serialized as Markdown')
                event.clipboardData.setData(MARKDOWN_MIME_TYPE, markdown)
                event.clipboardData.setData(PLAIN_TEXT_MIME_TYPE, markdown)
            }
            event.preventDefault()
            return true
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Selected content could not be copied' })
            return false
        }
    }, [config])

    const handlePaste = useCallback((event: PasteCommandType) => {
        const shifted = consumeShiftedIntent(pasteIntentRef.current)
        if (!config || config.readOnly || !('clipboardData' in event) || !event.clipboardData) return false

        try {
            const imageFile = clipboardImageFile(event.clipboardData)
            if (imageFile && config.imagePasteHandler) {
                event.preventDefault()
                void config.imagePasteHandler(imageFile, config.insertMarkdown).catch((error: unknown) => {
                    dialogService.error(error, { fallbackMessage: 'Clipboard image could not be pasted' })
                })
                return true
            }

            if (shifted) {
                const plainText = event.clipboardData.getData(PLAIN_TEXT_MIME_TYPE)
                if (!plainText) return false
                const selection = $getSelection()
                if (!$isRangeSelection(selection)) return false
                selection.insertText(plainText)
                event.preventDefault()
                return true
            }

            const markdown = event.clipboardData.getData(MARKDOWN_MIME_TYPE)
                || event.clipboardData.getData(PLAIN_TEXT_MIME_TYPE)
            if (!markdown) return false

            config.insertMarkdown(markdown)
            event.preventDefault()
            return true
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Clipboard content could not be pasted' })
            return false
        }
    }, [config])

    useEffect(() => {
        const unregisterKeyDown = editor.registerCommand(KEY_DOWN_COMMAND, handleKeyDown, COMMAND_PRIORITY_HIGH)
        const unregisterCopy = editor.registerCommand(COPY_COMMAND, handleCopy, COMMAND_PRIORITY_HIGH)
        const unregisterPaste = editor.registerCommand(PASTE_COMMAND, handlePaste, COMMAND_PRIORITY_HIGH)

        return () => {
            unregisterKeyDown()
            unregisterCopy()
            unregisterPaste()
        }
    }, [editor, handleCopy, handleKeyDown, handlePaste])

    return null
}

import { addComposerChild$, realmPlugin } from '@mdxeditor/editor'
import { markdownPasteConfig$, type MarkdownPasteConfig } from './markdown_paste_cell'
import { MarkdownPastePlugin } from './markdown_paste_plugin'

/** Connects Markdown-aware clipboard handling to MDXEditor's Lexical editor. */
export const markdownPastePlugin = realmPlugin<MarkdownPasteConfig>({
    init(realm, params) {
        if (!params) throw new Error('Markdown paste plugin requires parameters')

        realm.register(markdownPasteConfig$)
        realm.pub(markdownPasteConfig$, params)
        realm.pub(addComposerChild$, MarkdownPastePlugin)
    },
    update(realm, params) {
        if (!params) throw new Error('Markdown paste plugin requires parameters')

        realm.pub(markdownPasteConfig$, params)
    },
})

const crypto = require('node:crypto');
const { ActionAgentExecutor } = require('./action_agent_executor');
const { runCommand } = require('./action_command_executor');
const { ActionDefinitionCache } = require('./action_definition_cache');
const { resolveActionDefinition } = require('./action_definition_resolver');
const { ActionRun } = require('./action_run');
const { resolveAgentPrompt } = require('./action_text');
const { validatePreparePromptRequest, validateStartRequest } = require('./action_run_request');
const { assertReleasedCardActionAllowed } = require('../../../../shared/released_card_actions.mjs');

function createRunId() {
    return `action-${crypto.randomUUID()}`;
}

function activityOrigin(context) {
    if (context.kind === 'card' || context.kind === 'file') {
        if (typeof context.cardInternalId !== 'string' || context.cardInternalId.length === 0) {
            throw new Error('Card-origin action requires cardInternalId');
        }

        return { cardInternalId: context.cardInternalId, kind: 'card' };
    }

    return { kind: 'project' };
}

function hasStreamingAction(action, visited = new Set()) {
    if (visited.has(action.id)) return false;
    visited.add(action.id);
    if (action.type === 'agent' && action.streaming) return true;

    return [...action.onBefore, ...action.onAfter, ...action.on.map(({ action: linkedAction }) => linkedAction)]
        .some((linkedAction) => hasStreamingAction(linkedAction, visited));
}

class ActionRunnerService {
    constructor(dependencies) {
        this.actionWorktreeRunService = dependencies?.actionWorktreeRunService;
        this.agentConfigProvider = dependencies?.agentConfigProvider;
        this.agentRunnerService = dependencies?.agentRunnerService;
        this.commandRunner = dependencies?.commandRunner ?? runCommand;
        this.errorReporter = dependencies?.errorReporter ?? (() => undefined);
        this.localGitService = dependencies?.localGitService;
        this.actionDefinitionCache = dependencies?.actionDefinitionCache
            ?? (this.localGitService ? new ActionDefinitionCache({ localGitService: this.localGitService }) : null);
        this.agentExecutor = new ActionAgentExecutor({
            agentConfigProvider: this.agentConfigProvider,
            agentRunnerService: this.agentRunnerService,
            localGitService: this.localGitService,
        });
        this.actionsFolder = null;
        this.activeCardsFolder = null;
        this.actionCacheReady = null;
        this.completedRunResults = new Map();
        this.conversationReservations = new Map();
        this.configuredStates = [];
        this.runEvents = new Map();
        this.runs = new Map();
        this.listeners = new Set();
        this.project = null;
        this.projectFolder = null;
        this.releasesFolder = null;
        this.restartingRuns = new Set();
    }

    async startProject(project, actionsFolder, projectFolder, releasesFolder, activeCardsFolder) {
        if (typeof projectFolder !== 'string') throw new Error('Missing action runner projectFolder');
        if (typeof releasesFolder !== 'string' || releasesFolder.length === 0) throw new Error('Missing action runner releasesFolder');
        if (typeof activeCardsFolder !== 'string' || activeCardsFolder.length === 0) throw new Error('Missing action runner activeCardsFolder');
        if (this.project) await this.stop();
        this.project = project;
        this.actionsFolder = actionsFolder;
        this.activeCardsFolder = activeCardsFolder;
        this.projectFolder = projectFolder;
        this.releasesFolder = releasesFolder;
        this.actionCacheReady = this.actionDefinitionCache && this.localGitService
            ? this.initializeProject(project, actionsFolder)
            : null;

        return this.actionCacheReady ?? Promise.resolve();
    }

    async initializeProject(project, actionsFolder) {
        const [, config] = await Promise.all([
            this.actionDefinitionCache.startProject(project, actionsFolder),
            this.localGitService.loadProjectConfig(project),
        ]);
        const states = config?.states;
        if (!Array.isArray(states)) throw new Error('Invalid project states');
        this.configuredStates = states.map(({ state }) => {
            if (typeof state !== 'string' || state.length === 0) throw new Error('Invalid project state');

            return state;
        });
    }

    async stop() {
        const completions = [...this.runs.values()].map((run) => {
            run.cancel();

            return run.completion;
        });
        await Promise.all(completions);
        this.clearProject();
    }

    async suspend() {
        const completions = [...this.runs.values()].map((run) => {
            run.suspend();

            return run.completion;
        });
        await Promise.all(completions);
        this.clearProject();
    }

    clearProject() {
        this.project = null;
        this.actionsFolder = null;
        this.activeCardsFolder = null;
        this.actionCacheReady = null;
        this.projectFolder = null;
        this.releasesFolder = null;
        this.configuredStates = [];
        this.conversationReservations.clear();
        this.actionDefinitionCache?.stop();
    }

    subscribe(listener) {
        if (typeof listener !== 'function') throw new Error('Missing action run listener');
        this.listeners.add(listener);

        return () => this.listeners.delete(listener);
    }

    async start(request, options = {}) {
        const startRequest = validateStartRequest(request);
        this.requireReady();
        assertReleasedCardActionAllowed(startRequest.context, this.releasesFolder);
        const origin = activityOrigin(startRequest.context);
        const project = { ...this.project };
        const actionsFolder = this.actionsFolder;
        const rootAction = await this.loadRootAction(startRequest.actionId);
        if (options.interactive === false && hasStreamingAction(rootAction)) {
            throw new Error(`Streaming action requires an interactive manual run: ${rootAction.label}`);
        }
        const conversationReservation = this.consumeConversationReservation(startRequest, rootAction);
        const runId = createRunId();
        const run = new ActionRun({
            activeCardsFolder: this.activeCardsFolder,
            actionsFolder,
            activityOrigin: origin,
            context: startRequest.context,
            conversationReservation,
            runId,
            project,
            projectFolder: this.projectFolder,
            releasesFolder: this.releasesFolder,
            rootAction,
            runInput: startRequest.runInput,
            startedAt: new Date().toISOString(),
        }, {
            actionWorktreeRunService: this.actionWorktreeRunService,
            agentExecutor: this.agentExecutor,
            agentRunnerService: this.agentRunnerService,
            commandRunner: this.commandRunner,
            localGitService: this.localGitService,
            publisher: this.publish.bind(this),
        });
        this.runEvents.set(runId, []);
        this.runs.set(runId, run);
        run.start(this.finalizeRun.bind(this, run));

        return runId;
    }

    async reserveConversation(request) {
        const startRequest = validateStartRequest(request);
        this.requireReady();
        assertReleasedCardActionAllowed(startRequest.context, this.releasesFolder);
        if (startRequest.runInput.continueFrom) throw new Error('Continuing an agent conversation does not require a reservation');
        const action = await this.loadRootAction(startRequest.actionId);
        if (action.type !== 'agent') throw new Error('Cannot reserve a conversation for a command action');
