        });
        const { runner } = createRunner(undefined, { commandRunner });
        const runId = await runner.start({ actionId: 'main', context, runInput: {} });

        expect(() => runner.cancel('unknown')).toThrow('Unknown action run: unknown');
        runner.cancel(runId);
        resolve();
        await expect(runner.wait(runId)).resolves.toMatchObject({ status: 'cancelled' });
    });

    it('registers run before running-event listener can cancel it', async () => {
        const { commandRunner, runner } = createRunner();
        runner.subscribe((event) => {
            if (event.type === 'run' && event.status === 'running') runner.cancel(event.runId);
        });

        await expect(runToCompletion(runner)).resolves.toMatchObject({ status: 'cancelled' });
        expect(commandRunner).not.toHaveBeenCalled();
    });

    it('stop cancels every active run and clears project state', async () => {
        const { promise, resolve } = Promise.withResolvers();
        const commandRunner = vi.fn(async (_project, command, signal) => {
            await promise;
            if (signal.aborted) throw new Error('aborted');

            return { command, exitCode: 0, stderr: '', stdout: '' };
        });
        const { runner } = createRunner(undefined, { commandRunner });
        const firstId = await runner.start({ actionId: 'main', context, runInput: {} });
        const secondId = await runner.start({ actionId: 'main', context, runInput: {} });

        const stopping = runner.stop();
        resolve();
        await stopping;

        await expect(runner.wait(firstId)).resolves.toMatchObject({ status: 'cancelled' });
        await expect(runner.wait(secondId)).resolves.toMatchObject({ status: 'cancelled' });
        expect(() => runner.requireActionsFolder()).toThrow('Action runner has no actions folder');
    });

    it('isolates listeners and the error reporter from the result', async () => {
        const listenerError = new Error('listener failed');
        const errorReporter = vi.fn(() => { throw new Error('reporter failed'); });
        const { runner } = createRunner(undefined, { errorReporter });
        const laterListener = vi.fn();
        runner.subscribe(() => { throw listenerError; });
        runner.subscribe(laterListener);

        await expect(runToCompletion(runner)).resolves.toMatchObject({ status: 'completed' });
        expect(laterListener).toHaveBeenCalled();
        expect(errorReporter).toHaveBeenCalledWith(listenerError);
    });
});

import { createRequire } from 'node:module';
import path from 'node:path';
import { describe, expect, it, vi } from 'vitest';

const require = createRequire(import.meta.url);
const { ActionAgentExecutor } = require('./action_agent_executor');

const action = { agent: 'codex', id: 'main', label: 'Main', model: 'gpt-5.5', prompt: 'Review {{card-file}}', type: 'agent' };
const cardContext = { cardInternalId: 'card-1', file: 'design/card.md', kind: 'card' };
const project = { branch: 'main', rootPath: 'C:/repo' };

function conversation(overrides = {}) {
    return {
        cardInternalId: cardContext.cardInternalId,
        cardPath: cardContext.file,
        entries: [{ content: 'old answer', id: 'm1', kind: 'message', role: 'assistant', timestamp: '2026-01-01T00:00:00.000Z' }],
        id: 'conversation-1',
        providerSessions: [],
        ...overrides,
    };
}

function createExecutor(overrides = {}) {
    const agentRunnerService = {
        start: vi.fn(async (_project, _request, _onEvent, onComplete) => {
            onComplete(0, {
                conversation: { id: 'run-conversation' }, missingSession: false, reference: 'run.json',
                stderr: '', stdout: 'done', turnStarted: true,
            });

            return { runId: 'active-run' };
        }),
        stop: vi.fn(),
    };
    const localGitService = { loadAgentConversation: vi.fn(async () => conversation()) };
    const executor = new ActionAgentExecutor({
        agentConfigProvider: () => ({ agent: 'codex', agentProfiles: [], model: '' }),
        agentRunnerService,
        localGitService,
        ...overrides,
    });

    return { agentRunnerService, executor, localGitService };
}

function executionInput(overrides = {}) {
    return {
        action,
        activeCardsFolder: 'design/feature_descriptions',
        activityOrigin: { cardInternalId: 'card-1', kind: 'card' },
        context: cardContext,
        onActiveRunChange: vi.fn(),
        onEvent: vi.fn(),
        project,
        projectFolder: 'design',
        primaryProject: project,
        releasesFolder: 'design/releases',
        runInput: { extraPrompt: '' },
        signal: new AbortController().signal,
        ...overrides,
    };
}

describe('ActionAgentExecutor', () => {
    it('rejects unsupported streaming profiles before process start', async () => {
        const profile = { command: ['custom-agent'], models: ['default'], name: 'custom' };
        const agentConfigProvider = () => ({ agent: 'custom', agentProfiles: [profile], model: 'default' });
        const { agentRunnerService, executor } = createExecutor({ agentConfigProvider });
        const streamingAction = { ...action, agent: 'custom', model: 'default', streaming: true };

        await expect(executor.execute(executionInput({ action: streamingAction })))
            .rejects.toThrow('Agent profile does not support streaming: custom');
        expect(agentRunnerService.start).not.toHaveBeenCalled();
    });

