import type { Card, ProjectSnapshot } from '../../data/data_types'
import {
    CARD_ADDED_EVENT,
    CARD_CHANGED_EVENT,
    cardCollectionFieldChangedEvent,
    cardFieldChangedEvent,
    type DataService,
} from '../../services/data/data_service'
import { useCardColumnCards } from './use_card_column_cards'
